1	export type Customer = { yearsWithMHPCO: number };
2	export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
3	export type Quote = { premium: number; insuranceSum: number };
4	export type Policy = { items: Item[]; insuranceSum: number; paidOut?: number };
5	export type Damage = { itemType: string; amount: number };
6	export type Incident = { cause: string; damages: Damage[] };
7	export type ClaimResult = { payout: number; remainingCap: number; policy: Policy };
8	
9	// Components (runes, moonstones, …) share one price and can form "building blocks".
10	const COMPONENT_TYPES = ["rune", "moonstone"];
11	const COMPONENT_PRICE = 25;
12	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
13	  sword: 100,
14	  amulet: 60,
15	  staff: 80,
16	  potion: 40,
17	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_PRICE])),
18	};
19	const CURSE_SURCHARGE_PERCENT = 50;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
22	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
23	const LOYALTY_YEARS_THRESHOLD = 2;
24	const LOYALTY_DISCOUNT_PERCENT = 20;
25	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
26	const PROCESSING_FEE = 5;
27	// Every claim pays out damage minus a fixed deductible.
28	const DEDUCTIBLE = 100;
29	// Claims on very highly enchanted items (a stricter threshold than the premium surcharge) are only partly reimbursed.
30	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
31	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
32	// Price list: every item's insurance value is ten times its base premium (sword 1000/100, amulet 600/60, …).
33	const INSURANCE_VALUE_PER_PREMIUM = 10;
34	// Total payout per policy is capped at twice the insurance sum.
35	const PAYOUT_CAP_MULTIPLIER = 2;
36	
37	// A building block of exactly BLOCK_SIZE alike components is priced at BLOCK_PRICE instead of BLOCK_SIZE × COMPONENT_PRICE.
38	const BLOCK_SIZE = 3;
39	const BLOCK_PRICE = 60;
40	const COMPONENT_BLOCK_DISCOUNT = BLOCK_SIZE * COMPONENT_PRICE - BLOCK_PRICE;
41	
42	// Fractional amounts always round in MHPCO's favour: premiums up, payouts down.
43	const roundPremium = Math.ceil;
44	const roundPayout = Math.floor;
45	
46	// Integer-safe percent math: (base * percent) / 100 avoids float noise such as 115.00000000000001.
47	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
48	
49	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
50	
51	const basePremiumOf = (item: Item): number => {
52	  const premium = BASE_PREMIUM_BY_TYPE[item.type];
53	  if (premium === undefined) throw new Error(`Unknown item type: ${item.type}`);
54	  return premium;
55	};
56	
57	const insuranceValueOf = (item: Item): number => basePremiumOf(item) * INSURANCE_VALUE_PER_PREMIUM;
58	
59	const isHighlyEnchanted = (item: Item): boolean => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
60	
61	// Item-specific modifiers apply to the item's own base premium.
62	const itemSurcharge = (item: Item): number => {
63	  const base = basePremiumOf(item);
64	  return (
65	    (item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0) +
66	    (isHighlyEnchanted(item) ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT) : 0)
67	  );
68	};
69	
70	const countOfType = (items: Item[], type: string): number => items.filter((item) => item.type === type).length;
71	
72	const isBlock = (items: Item[], type: string): boolean => countOfType(items, type) === BLOCK_SIZE;
73	
74	const isLoyal = (customer: Customer): boolean => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
75	
76	// contractIndex is 0 for the customer's first contract; every later one is a follow-up.
77	const isFollowUpContract = (contractIndex: number): boolean => contractIndex > 0;
78	
79	// Policy-wide modifiers apply to the whole base premium; surcharges are positive, discounts negative.
80	const policyModifierPercents = (customer: Customer, contractIndex: number): number[] => [
81	  FIRST_INSURANCE_SURCHARGE_PERCENT,
82	  isLoyal(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0,
83	  isFollowUpContract(contractIndex) ? -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0,
84	];
85	
86	export const quote = (customer: Customer, items: Item[], contractIndex: number): Quote => {
87	  const blockCount = COMPONENT_TYPES.filter((type) => isBlock(items, type)).length;
88	  const listPrice = sum(items.map(basePremiumOf));
89	  const itemSurcharges = sum(items.map(itemSurcharge));
90	  const basePremium = listPrice - blockCount * COMPONENT_BLOCK_DISCOUNT;
91	  const policyModifiers = percentOf(basePremium, sum(policyModifierPercents(customer, contractIndex)));
92	  return {
93	    premium: roundPremium(basePremium + itemSurcharges + policyModifiers + PROCESSING_FEE),
94	    insuranceSum: sum(items.map(insuranceValueOf)),
95	  };
96	};
97	
98	const hasReducedReimbursement = (item: Item | undefined): boolean =>
99	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
100	
101	const reimbursementFor = (policy: Policy, damage: Damage): number => {
102	  const item = policy.items.find((candidate) => candidate.type === damage.itemType);
103	  return hasReducedReimbursement(item) ? percentOf(damage.amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT) : damage.amount;
104	};
105	
106	// The deductible is charged once per damaged item, not once per claim.
107	const payoutFor = (policy: Policy, damage: Damage): number => reimbursementFor(policy, damage) - DEDUCTIBLE;
108	
109	const payoutCapOf = (policy: Policy): number => policy.insuranceSum * PAYOUT_CAP_MULTIPLIER;
110	
111	// A fresh policy has no paidOut yet.
112	const paidOutOf = (policy: Policy): number => policy.paidOut ?? 0;
113	
114	const remainingCapOf = (policy: Policy): number => payoutCapOf(policy) - paidOutOf(policy);
115	
116	const countDamagesOfType = (damages: Damage[], type: string): number =>
117	  damages.filter((damage) => damage.itemType === type).length;
118	
119	// A claim may not report more damaged items of a type than the policy insures.
120	// This also rejects damages to item types the policy does not cover at all (insured count 0).
121	const assertDamagesCovered = (policy: Policy, damages: Damage[]): void => {
122	  for (const { itemType, amount } of damages) {
123	    if (amount < 0) throw new Error(`Negative damage amount: ${amount}`);
124	    if (countDamagesOfType(damages, itemType) > countOfType(policy.items, itemType)) {
125	      throw new Error(`More ${itemType} damages than insured ${itemType} items`);
126	    }
127	  }
128	};
129	
130	export const claim = (policy: Policy, incident: Incident): ClaimResult => {
131	  assertDamagesCovered(policy, incident.damages);
132	  const remainingBefore = remainingCapOf(policy);
133	  const desired = roundPayout(sum(incident.damages.map((damage) => payoutFor(policy, damage))));
134	  const payout = Math.min(desired, remainingBefore);
135	  return {
136	    payout,
137	    remainingCap: remainingBefore - payout,
138	    policy: { ...policy, paidOut: paidOutOf(policy) + payout },
139	  };
140	};
141

